using System.Text.Json;
using ChartForgeX.Markup.Mermaid;
using ChartForgeX.Mermaid;
using ChartForgeX.Themes;
using ChartForgeX.VisualArtifacts;
using Microsoft.Playwright;
using Xunit;
namespace ChartForgeX.Tests;
[Trait("BrowserSuite","Compatibility")]
public sealed class SequenceSourceDefaultsBrowserTests {
    [BrowserTheory] [InlineData(false,390)] [InlineData(true,390)] [InlineData(false,1100)] [InlineData(true,1100)]
    public async Task OmittedSourcePoliciesReachCompleteNativeTabsFootersLifelinesAndScrollableHosts(bool dark,int width) {
        var source=SequenceDefaultSourceFixture.Canonical();var options=new MermaidRenderOptions{WarningPolicy=MermaidWarningPolicy.Reject,Presentation=new MermaidPresentationOptions{ThemeMode=dark?VisualThemeMode.Dark:VisualThemeMode.Light,FontFamily=BrowserProofFonts.Family},Sequence=new MermaidSequenceRenderOptions{Width=width-32,Height=820}};var direct=MermaidRenderer.Render(source,options);Assert.Empty(direct.Diagnostics);var fence=new MermaidVisualMarkupParser(options).Parse("```mermaid\n"+source+"\n```");Assert.Empty(fence.Diagnostics);
        foreach(var pair in new[]{("direct",direct.Artifact!),("fence",Assert.Single(fence.Artifacts))}) {
            var html=pair.Item2.ToHtmlPage(new VisualArtifactRenderOptions{HtmlSizing=VisualArtifactHtmlSizing.PreserveSize});await using var session=await BrowserProofFonts.OpenAsync(html,width,900);var page=session.Page;var observed=await page.EvaluateAsync<JsonElement>("""
                () => {const s=document.querySelector('svg'),f=s.getBoundingClientRect();return {footers:[...s.querySelectorAll('[data-cfx-role="sequence-participant-footer"]')].map(e=>e.getAttribute('data-source-id')),texts:[...s.querySelectorAll('text')].map(t=>({text:t.textContent,size:parseFloat(getComputedStyle(t).fontSize),family:getComputedStyle(t).fontFamily,role:t.getAttribute('data-cfx-role')})),lifelines:[...s.querySelectorAll('[data-cfx-role="sequence-lifeline"]')].map(e=>({width:getComputedStyle(e).strokeWidth,dash:getComputedStyle(e).strokeDasharray,id:e.closest('[data-source-id]').getAttribute('data-source-id')})),curves:[...s.querySelectorAll('[data-cfx-role="sequence-message-line"]')].filter(p=>p.getAttribute('d').includes('C')).length,tabs:s.querySelectorAll('[data-cfx-role="sequence-fragment-tab"]').length,clip:[...s.querySelectorAll('text')].filter(t=>{const b=t.getBoundingClientRect();return b.width&&b.height&&(b.left<f.left-1.5||b.top<f.top-1.5||b.right>f.right+1.5||b.bottom>f.bottom+1.5)}).map(t=>t.textContent),scripts:s.querySelectorAll('script,foreignObject').length,overflow:document.documentElement.scrollWidth>innerWidth};}
                """);var output=Environment.GetEnvironmentVariable("CFX_BROWSER_CAPTURE_DIRECTORY");var stem="sequence-source-defaults-"+pair.Item1+"-"+width+(dark?"-dark":"-light");if(!string.IsNullOrWhiteSpace(output)){Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,stem+".mmd"),source);File.WriteAllText(Path.Combine(output,stem+".svg"),pair.Item2.ToSvg());File.WriteAllBytes(Path.Combine(output,stem+".native.png"),pair.Item2.ToPng());File.WriteAllText(Path.Combine(output,stem+".native.json"),pair.Item2.ToInterchangeJson());File.WriteAllText(Path.Combine(output,stem+".observed.json"),observed.GetRawText());await page.ScreenshotAsync(new PageScreenshotOptions{Path=Path.Combine(output,stem+".browser.png"),FullPage=true});}
            Assert.Equal(new[]{"A","B"},observed.GetProperty("footers").EnumerateArray().Select(e=>e.GetString()));Assert.Equal(1,observed.GetProperty("curves").GetInt32());Assert.Equal(1,observed.GetProperty("tabs").GetInt32());Assert.Equal(new[]{"A","B"},observed.GetProperty("lifelines").EnumerateArray().Select(e=>e.GetProperty("id").GetString()));Assert.All(observed.GetProperty("lifelines").EnumerateArray(),e=>{Assert.Equal("0.5px",e.GetProperty("width").GetString());Assert.Equal("none",e.GetProperty("dash").GetString());});foreach(var expected in new[]{("Review",14d),("Check",16d),("Complete note",14d),("Review work",16d),("loop",16d)}){var text=observed.GetProperty("texts").EnumerateArray().First(e=>e.GetProperty("text").GetString()==expected.Item1);Assert.Equal(expected.Item2,text.GetProperty("size").GetDouble());Assert.Contains(BrowserProofFonts.Family,text.GetProperty("family").GetString());}Assert.Empty(observed.GetProperty("clip").EnumerateArray());Assert.False(observed.GetProperty("overflow").GetBoolean());Assert.Equal(0,observed.GetProperty("scripts").GetInt32());var host=page.Locator("[data-cfx-html-sizing='preserve-size']");if(await host.EvaluateAsync<bool>("e=>e.scrollWidth>e.clientWidth")){await page.Keyboard.PressAsync("Tab"); Assert.True(await host.EvaluateAsync<bool>("node=>node.getRootNode().activeElement===node"), "The fresh static artifact host receives native Tab focus."); Assert.True(await host.EvaluateAsync<bool>("node=>node.matches(':focus-visible')"), "The static artifact host has keyboard-visible focus.");try {
                    await page.Keyboard.DownAsync("ArrowRight");
                    await page.WaitForFunctionAsync("()=>document.querySelector('[data-cfx-html-sizing=\"preserve-size\"]').scrollLeft>0");
                } finally { await page.Keyboard.UpAsync("ArrowRight"); }
                if(!string.IsNullOrWhiteSpace(output))await page.ScreenshotAsync(new PageScreenshotOptions{Path=Path.Combine(output,stem+".scrolled.browser.png"),FullPage=true});
            }
            InteractiveChartBrowser.AssertNoConsoleErrors(session);
        }
    }
}
